// ValidateConfirmConnectionsRequestBody runs the validations defined on
// ConfirmConnectionsRequestBody
func ValidateConfirmConnectionsRequestBody(body *ConfirmConnectionsRequestBody) (err error) {
	if body.Connections == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("connections", "body"))
	}
	if len(body.Connections) < 1 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.connections", body.Connections, len(body.Connections), 1, true))
	}
	if len(body.Connections) > 200 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.connections", body.Connections, len(body.Connections), 200, false))
	}
	for _, e := range body.Connections {
		if e != nil {
			if err2 := ValidateXaaConnectionConfirmationRequestBody(e); err2 != nil {
				err = goa.MergeErrors(err, err2)
			}
		}
	}
	return
}

// ValidateResetConnectionRequestBody runs the validations defined on
// ResetConnectionRequestBody
func ValidateResetConnectionRequestBody(body *ResetConnectionRequestBody) (err error) {
	if body.McpServerID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("mcp_server_id", "body"))
	}
	if body.McpServerID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.mcp_server_id", *body.McpServerID, goa.FormatUUID))
	}
	return
}

// ValidateXaaConnectionConfirmationRequestBody runs the validations defined on
// XaaConnectionConfirmationRequestBody
func ValidateXaaConnectionConfirmationRequestBody(body *XaaConnectionConfirmationRequestBody) (err error) {
	if body.McpServerID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("mcp_server_id", "body"))
	}
	if body.Audience == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("audience", "body"))
	}
	if body.McpServerID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.mcp_server_id", *body.McpServerID, goa.FormatUUID))
	}
	if body.Audience != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.audience", *body.Audience, goa.FormatURI))
	}
	if body.Audience != nil {
		err = goa.MergeErrors(err, goa.ValidatePattern("body.audience", *body.Audience, "^https://[^?#]+$"))
	}
	if body.Audience != nil {
		if utf8.RuneCountInString(*body.Audience) > 512 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.audience", *body.Audience, utf8.RuneCountInString(*body.Audience), 512, false))
		}
	}
	if body.OktaApplicationID != nil {
		if utf8.RuneCountInString(*body.OktaApplicationID) > 64 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.okta_application_id", *body.OktaApplicationID, utf8.RuneCountInString(*body.OktaApplicationID), 64, false))
		}
	}
	return
}
